import{_ as a,o as t,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const d=JSON.parse('{"title":"Residence permit and QID","description":"How the first residence permit and Qatar ID work, how to renew, what happens if the permit lapses, and leaving and returning.","frontmatter":{"title":"Residence permit and QID","description":"How the first residence permit and Qatar ID work, how to renew, what happens if the permit lapses, and leaving and returning.","lastChecked":"2026-10","sourceCount":11},"headers":[],"relativePath":"guide/residence-permit-and-qid.md","filePath":"guide/residence-permit-and-qid.md"}'),i={name:"guide/residence-permit-and-qid.md"};function s(n,e,f,l,p,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="residence-permit-and-qid" tabindex="-1">Residence permit and QID <a class="header-anchor" href="#residence-permit-and-qid" aria-label="Permalink to &quot;Residence permit and QID&quot;">​</a></h1><p>If you come to live in Qatar, you arrive on a residence visa and then apply for your first residence permit (RP). The Ministry of Interior (MOI) handles this as a First-Time Residence Permit service, and the application form is signed by your sponsor, either a company or an individual.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup></p><p>The fee for the ID card, known as the QID, is charged together with the residence permit, for the validity of the permit.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="how-to-get-your-first-permit" tabindex="-1">How to get your first permit <a class="header-anchor" href="#how-to-get-your-first-permit" aria-label="Permalink to &quot;How to get your first permit&quot;">​</a></h2><ol><li>Do the medical checkup within thirty days of entering Qatar.<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></li><li>Have your fingerprints taken after the medical is finished.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li><li>Prepare the documents for your sponsorship type, listed below.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>Submit them at the MOI Services Centres or Expatriate Affairs.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup></li></ol><h3 id="documents-for-company-sponsorship" tabindex="-1">Documents for company sponsorship <a class="header-anchor" href="#documents-for-company-sponsorship" aria-label="Permalink to &quot;Documents for company sponsorship&quot;">​</a></h3><ul><li>Labour contract attested by the Labour Department.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>Residence permit application form, printed and signed by the sponsor.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></li><li>Your original passport and your photo.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></li><li>A copy of the company&#39;s establishment ID.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>A blood group certificate.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li></ul><h3 id="documents-for-personal-sponsorship" tabindex="-1">Documents for personal sponsorship <a class="header-anchor" href="#documents-for-personal-sponsorship" aria-label="Permalink to &quot;Documents for personal sponsorship&quot;">​</a></h3><ul><li>Residence permit application form, printed and signed by the sponsor.<sup class="footnote-ref"><a href="#fn1" id="fnref1:9">[1]</a></sup></li><li>The original passport and a photo of the person being sponsored.<sup class="footnote-ref"><a href="#fn1" id="fnref1:10">[1]</a></sup></li><li>A blood group certificate.<sup class="footnote-ref"><a href="#fn1" id="fnref1:11">[1]</a></sup></li></ul><p>The current fees are listed on the same MOI page.<sup class="footnote-ref"><a href="#fn1" id="fnref1:12">[1]</a></sup></p><h2 id="how-to-renew" tabindex="-1">How to renew <a class="header-anchor" href="#how-to-renew" aria-label="Permalink to &quot;How to renew&quot;">​</a></h2><ul><li>You need the renewal form with the sponsor&#39;s authorized signature and stamp, the original passport, and the establishment ID of the company or the personal ID of the individual sponsor. The work permit and residence permit fees are paid at this stage.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li><li>You can renew at the Expatriates Affairs Department or MOI Services Centres, and the service is also available on the Metrash2 app and the MOI e-services portal.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></li><li>MOI says a renewal for 3 years gets a 20% discount on the fee.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li><li>To follow a renewal, use RP Renewal Tracking with the personal ID number of the sponsor or the RP holder.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li><li>To check when your documents expire, the Other Inquiries page covers the ID card, passport, RP and driving licence.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li></ul><h2 id="if-your-permit-lapses" tabindex="-1">If your permit lapses <a class="header-anchor" href="#if-your-permit-lapses" aria-label="Permalink to &quot;If your permit lapses&quot;">​</a></h2><p>MOI says an expired residence permit must be renewed within 90 days. After that a daily fine applies, up to a maximum, and the amounts are on the MOI tips page.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></p><h2 id="lost-damaged-or-changed-documents" tabindex="-1">Lost, damaged or changed documents <a class="header-anchor" href="#lost-damaged-or-changed-documents" aria-label="Permalink to &quot;Lost, damaged or changed documents&quot;">​</a></h2><ul><li>For a lost card, MOI lists a Lost Report service among its official documents services.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li>The Other Inquiries page has a smart card application form for residents that you can fill out and print.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup></li><li>If you get a new passport because the old one expired or was lost or damaged, there is a service to update your record. Bring the old and new passports and the application form, plus a Lost Report if the passport was lost. It is available on the Metrash2 app, at MOI Services Centres and at Passport Headquarters.<sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup></li></ul><h2 id="leaving-and-returning" tabindex="-1">Leaving and returning <a class="header-anchor" href="#leaving-and-returning" aria-label="Permalink to &quot;Leaving and returning&quot;">​</a></h2><ul><li>MOI has a free Leave Notification service for expatriates leaving the country on leave. It is available on the e-services portal, the Metrash2 app and at MOI Services Centres.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></li><li>The Exit &amp; Entry Permits page lets you check the expiry date of a leave notification.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></li><li>If you stay outside Qatar for more than 6 months, you need a return visa, and it depends on your residence permit still being valid. The sponsor applies through Metrash2, the e-services portal, Expatriate Affairs or MOI Services Centres.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup></li></ul><h2 id="cancelling-a-permit" tabindex="-1">Cancelling a permit <a class="header-anchor" href="#cancelling-a-permit" aria-label="Permalink to &quot;Cancelling a permit&quot;">​</a></h2><p>To cancel an RP, you and your sponsor both sign the application form, and the sponsor&#39;s personal ID or establishment ID is needed to verify the signature. It can also be done on Metrash2 and the e-services portal.<sup class="footnote-ref"><a href="#fn11" id="fnref11">[11]</a></sup></p><h2 id="tracking-an-application" tabindex="-1">Tracking an application <a class="header-anchor" href="#tracking-an-application" aria-label="Permalink to &quot;Tracking an application&quot;">​</a></h2><p>Use the Residency Permits inquiry page to follow an RP application with the visa number, or with the personal ID number of the sponsor, the agent or the authorized person. The same page has a Change Employer Application Enquiry.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup></p><p>See also: <a href="./arriving-and-visas">Arriving and visas</a>, <a href="./metrash">Metrash</a>, <a href="./family-visas">Family visas</a>, <a href="./work-and-labour-rights">Work and labour rights</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fresidence%2Bvisas%2Fyttyrttt" target="_blank" rel="noreferrer">First Time Residence Permit</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:10" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:11" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:12" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/47" target="_blank" rel="noreferrer">Tips &amp; Guidelines</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fresidence%2Bvisas%2Fegama1" target="_blank" rel="noreferrer">Residence Permit Renewal</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/residencypermits" target="_blank" rel="noreferrer">Residency Permits inquiry</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/others" target="_blank" rel="noreferrer">Other Inquiries</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?docId=a96cc4f1-23a6-4693-ae9e-179555192762&amp;viewType=CATEGORY" target="_blank" rel="noreferrer">Official Documents Services</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn7" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fresidence%2Bvisas%2Fiuytro" target="_blank" rel="noreferrer">Changing Passport information from an expired, lost or damaged passport to a new one</a>. Last checked: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn8" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fvisa%2Bcomplaints%2Fw456" target="_blank" rel="noreferrer">Leave Notification</a>. Last checked: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn9" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/exitservices" target="_blank" rel="noreferrer">Exit &amp; Entry Permits</a>. Last checked: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn10" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Freturn%2Bvisas%2Fvisa0127" target="_blank" rel="noreferrer">Return Visa on (more than 6 months outside the country)</a>. Last checked: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn11" class="footnote-item"><p>Ministry of Interior, <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fresidence%2Bvisas%2Fxcdsa" target="_blank" rel="noreferrer">Cancellation of Residence Permit</a>. Last checked: 2026-10. <a href="#fnref11" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',26)])])}const m=a(i,[["render",s]]);export{d as __pageData,m as default};
